import re, struct
from pathlib import Path
DOL = Path('orig/GEDE01/sys/main.dol').read_bytes()
CASES = (
    ('src/game/game_fn_801A6C58.c', 0x8023B0B0),
    ('src/game/game_fn_801A6CB4.c', 0x8023B190),
)
def dol_bytes(address, size):
    for off_base, addr_base, size_base, count in ((0, 0x48, 0x90, 7), (0x1c, 0x64, 0xac, 11)):
        for i in range(count):
            file_off = struct.unpack_from('>I', DOL, off_base + 4*i)[0]
            start = struct.unpack_from('>I', DOL, addr_base + 4*i)[0]
            length = struct.unpack_from('>I', DOL, size_base + 4*i)[0]
            if start <= address and address + size <= start + length:
                return DOL[file_off + address - start:file_off + address - start + size]
    raise ValueError(f'0x{address:08X} is not file-backed')
for source, address in CASES:
    entries = []
    for line in Path(source).read_text().splitlines():
        m = re.fullmatch(r'\s*\{\s*(0x[0-9A-Fa-f]+),\s*(\d+),\s*fn_([0-9A-Fa-f]{8}),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+)\s*\},', line)
        if m:
            entries.append((int(m[1], 0), int(m[2]), int(m[3], 16), *(int(m[i]) for i in range(4, 9))))
    retail = [struct.unpack_from('>8I', dol_bytes(address, len(entries) * 32), i * 32) for i in range(len(entries))]
    print(f'{source} retail=0x{address:08X} entries={len(entries)}')
    for i, (src, dol) in enumerate(zip(entries, retail)):
